sp_widget.client_script:
api.controller=function($scope, $window) {
    var c = this;


    c.detailPages = {
        rcl_id_001: 'receita_corrente',
        resultado_id_002: 'resultado_primario',
        despesa_id_003: 'despesa_pessoal',
        divida_id_004: 'divida_publica'
    };

    // Função chamada ao clicar no botão "Detalhar"
    c.detalhar = function(card) {
        // 1. Obtém o nome da página de destino com base no sys_id
        var pageId = c.detailPages[card.sys_id];

        if (pageId) {
            // 2. Constrói o URL e abre em uma nova aba
            // O URL é: ?id=<pageId>&sys_id=<sys_id_do_card>
            // Adicionamos o sys_id do card ao URL para que a página de destino saiba qual índice exibir.
            var url = "?id=" + pageId + "&sys_id=" + card.sys_id;

            $window.open(url, '_blank');
        } else {
            console.error("Página de destino não configurada para o card:", card.title);
            alert("Detalhes não disponíveis no momento.");
        }
    };
}

sp_widget.css:
/* 1. Estilos do Título Principal */
.main-title {
    font-family: 'Roboto', sans-serif; /* Assumindo que a fonte Roboto está disponível ou deve ser importada/configurada */
    font-weight: 700;
    font-size: 42px;
    line-height: 100%; /* Ajuste para o line-height desejado */
    color: #4671C4;
    margin-bottom: 40px; /* Espaço após o título e antes dos cards */
    padding: 10px 0;

}

/* 2. Estilos dos Cards */
.cards-row {
    margin-bottom: 20px; /* Espaçamento entre as linhas de cards */
}

.card-wrapper {
    padding: 10px; /* Espaço entre os cards */
}

.index-card {
    border: none;
    border-radius: 8px; /* Bordas arredondadas */
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1); /* Sombra para o efeito de elevação */
    padding: 15px;
    height: 100%; /* Garante que os cards da mesma linha tenham a mesma altura */
}

.card-title-index {
    font-size: 18px;
    font-weight: bold;
    color:#4671C4;
    margin-bottom: 15px;
    text-align: center; /* Centraliza o título dentro do card, se necessário */
}

/* 3. Estilo para a Área do Gráfico/Imagem */
.chart-image-placeholder {
    /* Simulando o espaço que o gráfico/imagem ocuparia */
    //background-color: #f7f9fc;
    border: 1px solid #eee;
     height: 24rem;/* Altura de exemplo para o gráfico */
    display: flex;
    align-items: center;
    justify-content: center;
    color: #666;
    font-size: 14px;
    margin-bottom: 10px;
}

/* 4. Estilo do Botão Detalhar */
.btn-detalhar {
    background-color: transparent;
    border: 1px solid #4671C4;
    color: #4671C4;
    font-weight: 600;
    padding: 5px 15px;
    border-radius: 4px;
    transition: all 0.3s ease;
}

.btn-detalhar:hover {
    background-color: #4671C4;
    color: #ffffff;
   transform: translateY(-5px); 
   box-shadow: 0 8px 15px rgba(0, 0, 0, 0.15);
}

/* 5. Centralização vertical e ajustes gerais (se necessário) */
.widget-container {
    max-width: 1200px; /* Limita a largura do conteúdo, se desejar */
    margin: auto;
    padding: 20px;
  	background-color: white;
}

.card-body > .text-end { /* Seleciona a div que contém o botão */
    display: flex;
    justify-content: flex-end; /* Alinha o item (botão) à direita */
    width: 100%; /* Garante que a div ocupe todo o espaço disponível */
    margin-top: 15px; /* Manter o espaço acima do botão */
}

/* ... SEU CSS ANTERIOR ... */

/* Novo estilo para garantir que a imagem preencha a div */
.chart-image-placeholder {
    /* ... estilos anteriores ... */
    height: 180px; /* Altura de exemplo para o gráfico */
    padding: 10px; /* Adiciona um pequeno padding interno */
}

.chart-image {
    max-width: 100%;
    max-height: 100%;
    object-fit: contain; /* Garante que a imagem caiba sem distorcer */
    display: block; /* Remove margem inferior indesejada */
}

